const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=s=>{const el=document.createElement('textarea');el.innerHTML=String(s??'').replace(/<[^>]*>/g,' ');return el.value.replace(/\s+/g,' ').trim()};
const safeURL=u=>{try{const p=new URL(u);return p.protocol==='https:'?p.href:'#'}catch{return '#'}};
