const vocabulary=['JavaScript','TypeScript','React','Vue','Angular','Node.js','Python','Java','C++','C#','PHP','Ruby','Go','Rust','SQL','PostgreSQL','MongoDB','AWS','Azure','Docker','Kubernetes','Git','HTML','CSS','Next.js','Figma','Sketch','Adobe','Photoshop','Illustrator','InDesign','UX','UI','User research','Product design','Graphic design','Branding','Design systems','Prototyping','Accessibility','Copywriting','Content','SEO','Marketing','Social media','Sales','Customer service','Customer support','CRM','Salesforce','HubSpot','Excel','Data analysis','Power BI','Tableau','Finance','Accounting','Bookkeeping','Project management','Product management','Agile','Scrum','Operations','Recruitment','Human resources','Teaching','Training','Writing','Editing','Translation','Healthcare','Nursing','Hospitality','Logistics','Administration','Legal','Compliance','Cybersecurity','Machine learning','Engineering','Communication','Leadership','Research'];
function has(text,term){return new RegExp('(^|[^a-z0-9])'+term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?=$|[^a-z0-9])','i').test(text)}
const knownSkills=new Set(vocabulary.map(s=>s.toLowerCase()));
let termFiles={},customMatches=new Map(),termRequests=new Map();
function score(job){const text=job.title+' '+job.tags.join(' ')+' '+job.description;return skills.filter(s=>Array.isArray(job.skillMatches)?(knownSkills.has(s.toLowerCase())?job.skillMatches.some(v=>v.toLowerCase()===s.toLowerCase()):has(text,s)||customMatches.get(s)?.has(job.searchId)):has(text,s))}
async function loadCustomSkills(){const files=termFiles;const custom=skills.filter(s=>!knownSkills.has(s.toLowerCase()));await Promise.all(custom.map(async skill=>{try{const tokens=[...new Set(skill.toLowerCase().match(/[a-z0-9]+/g)||[])];if(!tokens.length)return;const lists=await Promise.all(tokens.map(async token=>{const path=files[token.slice(0,2)];if(!path)return [];const url=new URL(path,location.href);if(url.origin!==location.origin||!url.pathname.includes('/api/terms/'))return [];if(!termRequests.has(url.href))termRequests.set(url.href,fetch(url.href,{signal:AbortSignal.timeout(15000)}).then(r=>{if(!r.ok)throw Error('Search unavailable');return r.json()}).catch(e=>{termRequests.delete(url.href);throw e}));return (await termRequests.get(url.href))[token]||[]}));if(files!==termFiles)return;const rest=lists.slice(1).map(a=>new Set(a));customMatches.set(skill,new Set((lists[0]||[]).filter(id=>rest.every(set=>set.has(id)))))}catch{/* Existing title and excerpt matches remain available offline. */}}));if(files===termFiles&&custom.length)render()}

function renderSkills(){loadCustomSkills();$('#profile').hidden=false;$('#skill-count').textContent=skills.length?skills.length+(skills.length===1?' skill':' skills'):'Your skills';$('#skills').innerHTML=skills.length?skills.map((s,i)=>`<button data-skill="${i}" aria-label="Remove ${esc(s)}"><span>${esc(s)}</span><svg viewBox="0 0 12 12" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true"><path d="m3 3 6 6m0-6-6 6" stroke-linecap="round"/></svg></button>`).join(''):'<p class="skills-empty">No skills yet. Add one below to shape your shortlist.</p>';render();}

function useText(text,label){if(text.trim().length<30)throw Error('We couldn’t find enough text. Try a text-based CV or paste your experience.');cvText=text;showReview(text);document.body.classList.add('has-cv');$('#cv-label').textContent='Your CV is ready';$('#cv-caption').textContent=label;$('#open-review').hidden=false;skills=vocabulary.filter(s=>has(text,s));$('#cv-status').textContent=label+' · '+skills.length+' skills found.';$('#cv').value='';$('#paste-details').open=false;limit=5;renderSkills()}
async function readFile(f){if(!f||$('#file').disabled)return;if(f.size>10*1024*1024){$('#cv-status').textContent='Please choose a file smaller than 10 MB.';return}$('#cv-status').textContent='Reading your CV on this device…';$('#drop').setAttribute('aria-busy','true');$('#file').disabled=true;try{let text='';const ext=f.name.split('.').pop().toLowerCase();if(ext==='txt')text=await f.text();else if(ext==='pdf'){if(!window.pdfjsLib)throw Error('PDF reader unavailable. Paste your CV text instead.');pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';const pdf=await pdfjsLib.getDocument({data:await f.arrayBuffer(),isEvalSupported:false}).promise;try{if(pdf.numPages>50)throw Error('Please use a CV with 50 pages or fewer.');for(let i=1;i<=pdf.numPages;i++){const page=await pdf.getPage(i);const content=await page.getTextContent();text+=content.items.map(t=>t.str+(t.hasEOL?'\n':' ')).join('')+'\n'}}finally{await pdf.destroy()}}else if(ext==='docx'){if(!window.mammoth)throw Error('DOCX reader unavailable. Paste your CV text instead.');text=(await mammoth.extractRawText({arrayBuffer:await f.arrayBuffer()})).value}else throw Error('Please choose a PDF, DOCX or TXT file.');useText(text,f.name)}catch(e){$('#cv-status').textContent=e.message||'Could not read this file. Please paste the text instead.'}finally{$('#file').value='';$('#file').disabled=false;$('#drop').removeAttribute('aria-busy')}}
function normalize(data,source){return(source==='Remotive'?data.jobs:data.data).map(j=>({id:source+':'+(j.id||j.slug),title:plain(j.title),company:plain(j.company_name),url:safeURL(j.url),location:plain(j.candidate_required_location||j.location||'Location not specified'),remote:source==='Remotive'||j.remote===true,type:plain(j.job_type||(j.job_types||[]).join(', ')).replace(/_/g,' ')||'See listing',salary:plain(j.salary||''),tags:(j.tags||[]).map(plain),description:plain(j.description),checkedAt:new Date().toISOString(),expiresAt:j.validThrough||j.expiryDate||null,date:source==='Remotive'?j.publication_date:new Date(j.created_at*1000).toISOString(),source}))}
function locationMatches(job,loc){if(!loc)return true;const aliases={'united kingdom':['united kingdom','uk','europe'],'uk':['united kingdom','uk','europe'],'usa':['usa','united states','north america','northern america'],'united states':['usa','united states','north america','northern america'],'spain':['spain','europe','eu'],'gibraltar':['gibraltar','europe'],'germany':['germany','deutschland','europe','eu'],'canada':['canada','north america','northern america']};return (aliases[loc]||[loc]).some(term=>has(job.location,term))||(job.remote&&/worldwide|anywhere|global/i.test(job.location))}
function titleWords(title){return title.toLowerCase().match(/[a-z]{3,}/g)?.filter(t=>!['the','and','for','with','remote','senior','junior','lead','manager','full','time'].includes(t))||[]}
function levelOf(title){return /head|director|lead|manager|chief/i.test(title)?'lead':/senior|staff|principal/i.test(title)?'senior':/junior|entry|intern|graduate/i.test(title)?'junior':'mid'}
function roleMatches(job){const role=$('#wanted-role').value.trim();if(!role)return true;const tokens=titleWords(role).map(t=>t.replace(/(?:ers?|ing|ment|s)$/,''));return tokens.some(t=>t.length>2&&job.title.toLowerCase().includes(t))}
function rank(job){let n=job.shared.length;const role=$('#wanted-role').value.trim();if(role){const words=titleWords(role);n+=words.filter(w=>has(job.title,w)).length*5}const level=$('#level').value;if(level)n+=levelOf(job.title)===level?3:-2;for(const f of feedback){if(f.reason==='role')n-=titleWords(job.title).filter(w=>f.tokens.includes(w)).length*2;if(f.reason==='level'&&levelOf(job.title)===f.level)n-=3;if(f.reason==='location'&&job.location.toLowerCase()===f.location)n-=4}return n}
function discoveryJobs(candidates){
 const broad=candidates.filter(j=>/worldwide|anywhere|global|europe|emea/i.test(j.location));
 const pool=!$('#location').value.trim()&&broad.length>=3?broad:candidates;
 const recent=[...pool].sort((a,b)=>(Date.parse(b.date)||0)-(Date.parse(a.date)||0)||Number(!!b.confirmedActive)-Number(!!a.confirmedActive));
 const chosen=[],companies=new Set(),families=new Set();
 const family=j=>/design|ux|creative/i.test(j.title)?'design':/engineer|developer|data|security/i.test(j.title)?'technical':/sales|marketing|content/i.test(j.title)?'commercial':/support|success|operations|people|finance/i.test(j.title)?'operations':'other';
 for(const diverse of [true,false])for(const job of recent){const company=job.company.toLowerCase(),group=family(job);if(chosen.length===3)return chosen;if(chosen.some(j=>j.id===job.id)||companies.has(company)||(diverse&&families.has(group)))continue;chosen.push(job);companies.add(company);families.add(group)}
 return chosen;
}

